// HasCharacter applies the HasEdge predicate on the "character" edge.
func HasCharacter() predicate.DowntimeActivity {
	return predicate.DowntimeActivity(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, CharacterTable, CharacterColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCharacterWith applies the HasEdge predicate on the "character" edge with a given conditions (other predicates).
func HasCharacterWith(preds ...predicate.Character) predicate.DowntimeActivity {
	return predicate.DowntimeActivity(func(s *sql.Selector) {
		step := newCharacterStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DowntimeActivity) predicate.DowntimeActivity {
	return predicate.DowntimeActivity(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DowntimeActivity) predicate.DowntimeActivity {
	return predicate.DowntimeActivity(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DowntimeActivity) predicate.DowntimeActivity {
	return predicate.DowntimeActivity(sql.NotPredicates(p))
}
